INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(312242, 23425, 6202, '<td valign="top">Wonderful expression.  The black and white makes this photo.</td>', 'Wonderful expression.  The black and white makes this photo.', '2003-06-02 01:06:42.000000', NULL, 1),
(312249, 23516, 6202, '<td valign="top">Not only does this sound it, it looks good.  Great capture can almost hear the bacon sizzling as it is cooking.</td>', 'Not only does this sound it, it looks good.  Great capture can almost hear the bacon sizzling as it is cooking.', '2003-06-02 01:09:48.000000', NULL, 1),
(312251, 23394, 3280, '<td valign="top">Fantastic shot!  Very well done, the colors are great and the expression on the little ones face is priceless!  Looks like a winner to me! 10</td>', 'Fantastic shot!  Very well done, the colors are great and the expression on the little ones face is priceless!  Looks like a winner to me! 10', '2003-06-02 01:10:11.000000', NULL, 1),
(312252, 23517, 5391, '<td valign="top">I''ve started a new habit of picking my favorite thumbnail and voting on it first in each challenge, rather than just starting with the first random one to pop up.  This is my favorite this week.  Great lighting, great sharpness.  On closer inspection, I''d like to see just that very tiny bit of the top of the headphones that seems to be missing, but otherwise perfect.  Great shot!  9</td>', 'I''ve started a new habit of picking my favorite thumbnail and voting on it first in each challenge, rather than just starting with the first random one to pop up.  This is my favorite this week.  Great lighting, great sharpness.  On closer inspection, I''d like to see just that very tiny bit of the top of the headphones that seems to be missing, but otherwise perfect.  Great shot!  9', '2003-06-02 01:10:18.000000', NULL, 1),
(312259, 23425, 4967, '<td valign="top">Is this Carsten?  Another one of the lovely twins?  Interesting photo... but I don''t think it conveys sound to us as the viewer... because it''s contained to the boy.  I would have liked it if say he was singing along to it... that might have helped... beautfiul portrait though... very nice lighting... Nice photo, but to me this doesn''t get sound out... -6-</td>', 'Is this Carsten?  Another one of the lovely twins?  Interesting photo... but I don''t think it conveys sound to us as the viewer... because it''s contained to the boy.  I would have liked it if say he was singing along to it... that might have helped... beautfiul portrait though... very nice lighting... Nice photo, but to me this doesn''t get sound out... -6-', '2003-06-02 01:16:02.000000', NULL, 1),
(312260, 23529, 255, '<td valign="top">man this is great! love the dof and her expression--and especially the angle. nice work.</td>', 'man this is great! love the dof and her expression--and especially the angle. nice work.', '2003-06-02 01:17:33.000000', NULL, 1),
(312263, 23394, 4967, '<td valign="top">This is absolutely beautiful... can you actually hear heartbeats through the stomach?  Wow... this is one touching photo... If this is your family then I would definitely get this picture printed and also congrats on an upcoming new child!  I really think this is beautifully done!  I like the lighting... I''m giving this a -10- because it really catches my eye and is sweet beyond belief!</td>', 'This is absolutely beautiful... can you actually hear heartbeats through the stomach?  Wow... this is one touching photo... If this is your family then I would definitely get this picture printed and also congrats on an upcoming new child!  I really think this is beautifully done!  I like the lighting... I''m giving this a -10- because it really catches my eye and is sweet beyond belief!', '2003-06-02 01:19:53.000000', NULL, 1),
(312265, 23502, 6202, '<td valign="top">I got one of these too, it was my Grandfathers, why didn''t I think of it...lol  Good representation of sound.</td>', 'I got one of these too, it was my Grandfathers, why didn''t I think of it...lol  Good representation of sound.', '2003-06-02 01:21:22.000000', NULL, 1),
(312270, 23518, 4967, '<td valign="top">I like this because you actually showed the movement in the finger... if not for that, I would just have thought the guy was sitting there holding a guitar.  Nicely composed as well, I like the close up perspective.  Great contrasts in this photo.  It kind of bothers me that the arm in the back gets slightly lost, but it''s not a huge thing.  Otherwise absolutely beautifully done.  -9-</td>', 'I like this because you actually showed the movement in the finger... if not for that, I would just have thought the guy was sitting there holding a guitar.  Nicely composed as well, I like the close up perspective.  Great contrasts in this photo.  It kind of bothers me that the arm in the back gets slightly lost, but it''s not a huge thing.  Otherwise absolutely beautifully done.  -9-', '2003-06-02 01:22:56.000000', NULL, 1),
(312271, 23370, 4967, '<td valign="top">LOL... this is wonderful... very very well done... really gives a sense of sound, and loudness... I''d prolly be covering my ears as well.  This is just fantastic... beautiful job!  the one thing I might have liked to see is the lips of the person blowing the horn.  Still I think I would put it a 9 but for creativity I''m giving it a -10- nice job!</td>', 'LOL... this is wonderful... very very well done... really gives a sense of sound, and loudness... I''d prolly be covering my ears as well.  This is just fantastic... beautiful job!  the one thing I might have liked to see is the lips of the person blowing the horn.  Still I think I would put it a 9 but for creativity I''m giving it a -10- nice job!', '2003-06-02 01:25:02.000000', NULL, 1),
(312272, 23328, 4967, '<td valign="top">This would have been more effective if you slowed the shutter speed, and got the persons hands really moving along the keyboard of the piano... it would have been nice to see some action and show the person really playing rather than just resting a hand there...</td>', 'This would have been more effective if you slowed the shutter speed, and got the persons hands really moving along the keyboard of the piano... it would have been nice to see some action and show the person really playing rather than just resting a hand there...', '2003-06-02 01:26:55.000000', NULL, 1),
(312274, 23532, 4967, '<td valign="top">I can''t tell that the lights are flashing, or that the wheels are turning... there''s no movement here... and was the truck even moving with sirens blasting?  I don''t get the feeling of sound.  Sorry...</td>', 'I can''t tell that the lights are flashing, or that the wheels are turning... there''s no movement here... and was the truck even moving with sirens blasting?  I don''t get the feeling of sound.  Sorry...', '2003-06-02 01:29:00.000000', NULL, 1),
(312276, 23394, 6202, '<td valign="top">Beautiful.  I love the feeling of this photo.  10</td>', 'Beautiful.  I love the feeling of this photo.  10', '2003-06-02 01:30:39.000000', NULL, 1),
(312277, 23539, 4967, '<td valign="top">I would have suggested slowing the shutter speed so that you could get movement from the record.  That would have given more a sense of sound I think.</td>', 'I would have suggested slowing the shutter speed so that you could get movement from the record.  That would have given more a sense of sound I think.', '2003-06-02 01:30:59.000000', NULL, 1),
(312278, 23448, 1143, '<td valign="top">great shot. not making me think of a sound right off but I LOVE the blues</td>', 'great shot. not making me think of a sound right off but I LOVE the blues', '2003-06-02 01:31:36.000000', NULL, 1),
(312279, 22947, 4967, '<td valign="top">Good job with the motion of the record!  Gives a lot more sense of sound than just stopping action... what record am I listening to?  &lt;GRIN&gt;</td>', 'Good job with the motion of the record!  Gives a lot more sense of sound than just stopping action... what record am I listening to?  <GRIN>', '2003-06-02 01:32:13.000000', NULL, 1),
(312280, 23314, 4967, '<td valign="top">Oh gees!  I would have gone insane taking this photo!  VERY VERY WELL DONE... Gives off a very good sense of sound!  -10-  I like your cropping, and the second hand is awesome... and the bell moving to set off the alarm... everything is just very well done... congrats!</td>', 'Oh gees!  I would have gone insane taking this photo!  VERY VERY WELL DONE... Gives off a very good sense of sound!  -10-  I like your cropping, and the second hand is awesome... and the bell moving to set off the alarm... everything is just very well done... congrats!', '2003-06-02 01:34:07.000000', NULL, 1),
(312298, 23379, 714, '<td valign="top">I love this shot.  It put a smile on my face looking at her.  10</td>', 'I love this shot.  It put a smile on my face looking at her.  10', '2003-06-02 02:02:33.000000', NULL, 1),
(312300, 23185, 714, '<td valign="top">Great picture for the challenge.  I like the duotones.  Good luck</td>', 'Great picture for the challenge.  I like the duotones.  Good luck', '2003-06-02 02:03:48.000000', NULL, 1),
(312301, 23407, 714, '<td valign="top">Those things are so noisey.  Have you ever listened to them after you put them in your mouth?  hahaha...good stuff.  great photo.</td>', 'Those things are so noisey.  Have you ever listened to them after you put them in your mouth?  hahaha...good stuff.  great photo.', '2003-06-02 02:05:13.000000', NULL, 1),
(312302, 23234, 3669, '<td valign="top">I really like the lighting and of this photo.  It is crisp and clean.  The duotone is fitting.  I feel it meets challenge.  I only wish I could see more of the face of the performer.  8  Good luck in the challenge.</td>', 'I really like the lighting and of this photo.  It is crisp and clean.  The duotone is fitting.  I feel it meets challenge.  I only wish I could see more of the face of the performer.  8  Good luck in the challenge.', '2003-06-02 02:06:12.000000', NULL, 1),
(312305, 23421, 714, '<td valign="top">What an awesome sight.  I could sit and watch this forever.  Good luck.</td>', 'What an awesome sight.  I could sit and watch this forever.  Good luck.', '2003-06-02 02:07:09.000000', NULL, 1),
(312306, 23425, 6405, '<td valign="top">Is that Olympus 5050?,very sharp pic,10 from me!</td>', 'Is that Olympus 5050?,very sharp pic,10 from me!', '2003-06-02 02:07:44.000000', NULL, 1),
(312307, 22855, 714, '<td valign="top">Very nice and clean.  I love it.  10</td>', 'Very nice and clean.  I love it.  10', '2003-06-02 02:08:28.000000', NULL, 1),
(312311, 23308, 3669, '<td valign="top">Very nice...definately meets the challenge.  I like how you were able to portray the vibrating string as it is being played.  Nice touch.  Focus is excellent.  You picked up the lines well in this well used instrument. 9 Good luck in the challenge.</td>', 'Very nice...definately meets the challenge.  I like how you were able to portray the vibrating string as it is being played.  Nice touch.  Focus is excellent.  You picked up the lines well in this well used instrument. 9 Good luck in the challenge.', '2003-06-02 02:10:26.000000', NULL, 1),
(312312, 23357, 714, '<td valign="top">oh ya! I can hear the sounds here.  The wind blowing through the big mountain pinetrees.  The fish jumping in the water every so often that catches your attention.  An occasional bird flying through the air.  What a beautiful picture.  I love the mountains.  10</td>', 'oh ya! I can hear the sounds here.  The wind blowing through the big mountain pinetrees.  The fish jumping in the water every so often that catches your attention.  An occasional bird flying through the air.  What a beautiful picture.  I love the mountains.  10', '2003-06-02 02:11:01.000000', NULL, 1),
(312314, 23511, 714, '<td valign="top">this is a great shot.  Very creative indeed.  I like that poem.  9</td>', 'this is a great shot.  Very creative indeed.  I like that poem.  9', '2003-06-02 02:12:58.000000', NULL, 1),
(312316, 23220, 714, '<td valign="top">Great picture. Nice and clear.  I like the background.  Good job and good luck.</td>', 'Great picture. Nice and clear.  I like the background.  Good job and good luck.', '2003-06-02 02:14:43.000000', NULL, 1),
(312318, 22876, 714, '<td valign="top">No Way!  Did that really happen?  Great shot.  I hope you didn''t get hurt from this.  Good luck.</td>', 'No Way!  Did that really happen?  Great shot.  I hope you didn''t get hurt from this.  Good luck.', '2003-06-02 02:15:47.000000', NULL, 1),
(312319, 23538, 3669, '<td valign="top">If I''m not mistaking, this is the exhast system of the car.  Wouldn''t  the vroom sound would come from the engine?  Also, something about the colors in this picture just doesn''t seem right.  I do like the refections of the pipes.  It is well focused and does make a somewhat abstract-y photo.   <br/></td>', 'If I''m not mistaking, this is the exhast system of the car.  Wouldn''t  the vroom sound would come from the engine?  Also, something about the colors in this picture just doesn''t seem right.  I do like the refections of the pipes.  It is well focused and does make a somewhat abstract-y photo.   ', '2003-06-02 02:15:49.000000', NULL, 1),
(312320, 23002, 714, '<td valign="top">Great lighting and good use of shutter speed. Great angle.  Good luck!</td>', 'Great lighting and good use of shutter speed. Great angle.  Good luck!', '2003-06-02 02:17:10.000000', NULL, 1),
(312323, 23335, 6405, '<td valign="top">Just an beautiful shot, perfect timing, 10 here!</td>', 'Just an beautiful shot, perfect timing, 10 here!', '2003-06-02 02:19:26.000000', NULL, 1),
(312324, 23372, 3669, '<td valign="top">Oh, yes...I can relate.  Those kind of beings CAN make a lot of noise.  I like the action of the hands.  Nice family snapshot and looks as if they had a lot of fun posing for it.  I think it would have portrayed noise just a little better if the kids would of had their faces more toward the camera to see their expressions.</td>', 'Oh, yes...I can relate.  Those kind of beings CAN make a lot of noise.  I like the action of the hands.  Nice family snapshot and looks as if they had a lot of fun posing for it.  I think it would have portrayed noise just a little better if the kids would of had their faces more toward the camera to see their expressions.', '2003-06-02 02:20:11.000000', NULL, 1),
(312326, 22876, 6405, '<td valign="top">Looks like you had spots on the camera lens,perfect timing,9 from me!</td>', 'Looks like you had spots on the camera lens,perfect timing,9 from me!', '2003-06-02 02:20:29.000000', NULL, 1),
(312328, 23517, 6405, '<td valign="top">Great light and well done, 10 from me!</td>', 'Great light and well done, 10 from me!', '2003-06-02 02:21:26.000000', NULL, 1),
(312331, 23378, 3669, '<td valign="top">That is a beautiful picture of Liberty!  The lighting and framing are absolutely perfect.  Shows great detail to.  I like your take on the challenge.  I wish you the best of luck in the challenge. 10 in my book</td>', 'That is a beautiful picture of Liberty!  The lighting and framing are absolutely perfect.  Shows great detail to.  I like your take on the challenge.  I wish you the best of luck in the challenge. 10 in my book', '2003-06-02 02:21:59.000000', NULL, 1),
(312332, 23002, 6405, '<td valign="top">Excellent timing and good contrast 10 from me!</td>', 'Excellent timing and good contrast 10 from me!', '2003-06-02 02:22:26.000000', NULL, 1),
(312334, 23525, 6405, '<td valign="top">Not so soundy, but I love the timing of the water coming out,9 from me!</td>', 'Not so soundy, but I love the timing of the water coming out,9 from me!', '2003-06-02 02:23:35.000000', NULL, 1),
(312339, 23496, 3669, '<td valign="top">This is absolutely beautiful and breath takingl!!  Just looking at it, I feel I could hear the water flowing.  I would really like to know how to get the satiny look to the water.  I realize that it is probably done using a longer exposure, but how do you get it from being OVER exposed?  Mine have all turned out washed out (no pun intended).  I really like the lighting and the glittering rocks.  I''m highly impressed.  10</td>', 'This is absolutely beautiful and breath takingl!!  Just looking at it, I feel I could hear the water flowing.  I would really like to know how to get the satiny look to the water.  I realize that it is probably done using a longer exposure, but how do you get it from being OVER exposed?  Mine have all turned out washed out (no pun intended).  I really like the lighting and the glittering rocks.  I''m highly impressed.  10', '2003-06-02 02:27:46.000000', NULL, 1),
(312345, 23357, 3669, '<td valign="top">Beautiful!!  Did you catch anything?  Beautiful sky, beautiful reflection in the calm water and beautiful colors.  I like your take on the challenge.  I wish you the best of luck in the scoring. 8</td>', 'Beautiful!!  Did you catch anything?  Beautiful sky, beautiful reflection in the calm water and beautiful colors.  I like your take on the challenge.  I wish you the best of luck in the scoring. 8', '2003-06-02 02:32:21.000000', NULL, 1),
(312350, 22876, 4267, '<td valign="top">great capture... how did ya break the glass?</td>', 'great capture... how did ya break the glass?', '2003-06-02 02:40:30.000000', NULL, 1),
(312351, 23520, 3669, '<td valign="top">This picture seems to portray action more than sound in my opinion.  Therefore, as an action shot, it is done well.  It is nicely focused and I like the reflection of the surfer in the water.  I''m not sure as I like the over-exposed look.  I would like to have seen some detail of the waves on the right.</td>', 'This picture seems to portray action more than sound in my opinion.  Therefore, as an action shot, it is done well.  It is nicely focused and I like the reflection of the surfer in the water.  I''m not sure as I like the over-exposed look.  I would like to have seen some detail of the waves on the right.', '2003-06-02 02:40:50.000000', NULL, 1),
(312352, 23453, 3669, '<td valign="top">Very nice close-up!!  Focus and DOF are nice.  The duck really pops out.  Great detail.  He looks like he''s warning you to get out of his space.  Good job.  8  Good luck in the challenge.</td>', 'Very nice close-up!!  Focus and DOF are nice.  The duck really pops out.  Great detail.  He looks like he''s warning you to get out of his space.  Good job.  8  Good luck in the challenge.', '2003-06-02 02:43:34.000000', NULL, 1),
(312357, 23407, 3669, '<td valign="top">Very good idea and nicely done.  I like your set-up and the colors.  Good detail on the rice krispies.  I also really like how you did your border.  I think your picture would have been even better, though, had the background been blocked somehow between the cereal box and the cup to avoid the light reflections.  They are a distraction.  My score = 7  Good luck in the challenge.</td>', 'Very good idea and nicely done.  I like your set-up and the colors.  Good detail on the rice krispies.  I also really like how you did your border.  I think your picture would have been even better, though, had the background been blocked somehow between the cereal box and the cup to avoid the light reflections.  They are a distraction.  My score = 7  Good luck in the challenge.', '2003-06-02 02:50:51.000000', NULL, 1),
(312362, 23421, 3669, '<td valign="top">Yes, this meets the challenge in my opinion.  Not only the waves, but the sounds of the birds flying overhead.  There is just something about this photo that doesn''t seem make me say WOW though.  Perhaps a closer crop and a little boost in the saturation to make the waves more dramatic and bring more color out.  Just a thought.  Good luck in the challenge.</td>', 'Yes, this meets the challenge in my opinion.  Not only the waves, but the sounds of the birds flying overhead.  There is just something about this photo that doesn''t seem make me say WOW though.  Perhaps a closer crop and a little boost in the saturation to make the waves more dramatic and bring more color out.  Just a thought.  Good luck in the challenge.', '2003-06-02 02:59:41.000000', NULL, 1),
(312365, 23543, 3669, '<td valign="top">Very nice idea.  I think I would have liked to see more focus on the water.  Plus, I think there was a little too much lighting from above.  The reflective light is a distraction.  However, the concept of your photo is great.</td>', 'Very nice idea.  I think I would have liked to see more focus on the water.  Plus, I think there was a little too much lighting from above.  The reflective light is a distraction.  However, the concept of your photo is great.', '2003-06-02 03:03:13.000000', NULL, 1),
(312368, 23516, 3669, '<td valign="top">Very good idea!!  Just looking at this, I can hear the sizzle.  I love campfire cooking.  Great detail of the bubbles in the bacon grease.  I think, though, that it''s a little overexposed, especially on the bacon that isn''t cooked all the way yet.  Doesn''t really make it look very appealing.</td>', 'Very good idea!!  Just looking at this, I can hear the sizzle.  I love campfire cooking.  Great detail of the bubbles in the bacon grease.  I think, though, that it''s a little overexposed, especially on the bacon that isn''t cooked all the way yet.  Doesn''t really make it look very appealing.', '2003-06-02 03:09:40.000000', NULL, 1),
(312370, 23168, 8843, '<td valign="top">I can almost smell it yummm too bad it''s blurry!</td>', 'I can almost smell it yummm too bad it''s blurry!', '2003-06-02 03:11:02.000000', NULL, 1),
(312371, 23421, 8682, '<td valign="top">WOW... REALLY, YOU WAS IN THE RIGHT PLACE AT THE RIGHT TIME.... Beatiful...<br/>10</td>', 'WOW... REALLY, YOU WAS IN THE RIGHT PLACE AT THE RIGHT TIME.... Beatiful...10', '2003-06-02 03:11:19.000000', NULL, 1),
(312374, 23518, 8682, '<td valign="top">Español?</td>', 'Español?', '2003-06-02 03:15:37.000000', NULL, 1),
(312377, 23401, 3669, '<td valign="top">Hmm...very interesting photo.  I assume you mean for the smoke to represent air that passes through the flute that makes the sound as it''s being played.  However, no one is playing it, therefore making it magic I suppose.  I really like the effect of the swirls of smoke, the lighting and your origionality.</td>', 'Hmm...very interesting photo.  I assume you mean for the smoke to represent air that passes through the flute that makes the sound as it''s being played.  However, no one is playing it, therefore making it magic I suppose.  I really like the effect of the swirls of smoke, the lighting and your origionality.', '2003-06-02 03:17:56.000000', NULL, 1),
(312381, 23472, 3669, '<td valign="top">Please forgive me... I''m not understanding this photo and what I''m looking at.  The colors are nice but I don''t know what it and Manitoba have to do with sound.  Am I missing something?</td>', 'Please forgive me... I''m not understanding this photo and what I''m looking at.  The colors are nice but I don''t know what it and Manitoba have to do with sound.  Am I missing something?', '2003-06-02 03:24:52.000000', NULL, 1),
(312385, 23394, 3669, '<td valign="top">Beautiful photography.  Excellent lighting and skin tones.  Lovely and unique take on the challenge.</td>', 'Beautiful photography.  Excellent lighting and skin tones.  Lovely and unique take on the challenge.', '2003-06-02 03:34:47.000000', NULL, 1),
(312386, 23427, 3669, '<td valign="top">Nice picture, however, I think a drumstick or two would be appropriate to make it more complete.</td>', 'Nice picture, however, I think a drumstick or two would be appropriate to make it more complete.', '2003-06-02 03:36:19.000000', NULL, 1),
(312387, 23463, 6349, '<td valign="top">great photo.  not to "sound" to me.  then again, neither is my entry!  lol.  i give it a 9 and wish you the best of luck.</td>', 'great photo.  not to "sound" to me.  then again, neither is my entry!  lol.  i give it a 9 and wish you the best of luck.', '2003-06-02 03:38:35.000000', NULL, 1),
