(312389, 23528, 6349, '<td valign="top">oh man, that dart should be fully in the frame.  great idea.  great execution.  a little too grainy in the blue.</td>', 'oh man, that dart should be fully in the frame.  great idea.  great execution.  a little too grainy in the blue.', '2003-06-02 03:40:17.000000', NULL, 1),
