(312638, 23529, 327, '<td valign="top">Very good lighting, composition and color.</td>', 'Very good lighting, composition and color.', '2003-06-02 10:57:51.000000', NULL, 1),
(312641, 22855, 327, '<td valign="top">lol....real nice. Good work.</td>', 'lol....real nice. Good work.', '2003-06-02 11:01:09.000000', NULL, 1),
(312642, 22936, 327, '<td valign="top">nice, really a cool shot.</td>', 'nice, really a cool shot.', '2003-06-02 11:01:51.000000', NULL, 1),
(312648, 23453, 327, '<td valign="top">lol</td>', 'lol', '2003-06-02 11:07:26.000000', NULL, 1),
(312666, 23054, 7707, '<td valign="top">A little too harsh on the lighting for my taste</td>', 'A little too harsh on the lighting for my taste', '2003-06-02 11:32:03.000000', NULL, 1),
(312667, 23463, 3102, '<td valign="top">A neat shot -- the fog is great!  It feels like it should be rotated just slightly to the right, but that could just be my perception.</td>', 'A neat shot -- the fog is great!  It feels like it should be rotated just slightly to the right, but that could just be my perception.', '2003-06-02 11:32:34.000000', NULL, 1),
(312668, 23394, 3102, '<td valign="top">Great shot!  Certainly one you''ll want to keep for posterity! - 10</td>', 'Great shot!  Certainly one you''ll want to keep for posterity! - 10', '2003-06-02 11:33:36.000000', NULL, 1),
(312669, 23425, 7707, '<td valign="top">Great quality photo, but I loose a little of the feeling of "sound" as it''s too croped around the face.</td>', 'Great quality photo, but I loose a little of the feeling of "sound" as it''s too croped around the face.', '2003-06-02 11:33:37.000000', NULL, 1),
(312670, 23525, 3102, '<td valign="top">I''ll bet you went through a lot of attempts before you were able to capture that!  Very well done!</td>', 'I''ll bet you went through a lot of attempts before you were able to capture that!  Very well done!', '2003-06-02 11:34:14.000000', NULL, 1),
(312671, 23314, 3102, '<td valign="top">Excellent clarity -- great subject!  Great job capturing the motion of the doohickey (technical term) that strikes the bells!</td>', 'Excellent clarity -- great subject!  Great job capturing the motion of the doohickey (technical term) that strikes the bells!', '2003-06-02 11:36:16.000000', NULL, 1),
(312672, 22855, 7707, '<td valign="top">Great idea, photo is a bit washed in my opinion</td>', 'Great idea, photo is a bit washed in my opinion', '2003-06-02 11:36:28.000000', NULL, 1),
(312675, 23503, 3102, '<td valign="top">I like the idea of capturing the speaker in motion as the bass moves it... but I think this may have been stronger had you included more of the speaker.  This way, the rest of the speaker would have been in focus, providing emphasis on the blurred woofer as it moves.</td>', 'I like the idea of capturing the speaker in motion as the bass moves it... but I think this may have been stronger had you included more of the speaker.  This way, the rest of the speaker would have been in focus, providing emphasis on the blurred woofer as it moves.', '2003-06-02 11:39:36.000000', NULL, 1),
(312676, 23516, 3102, '<td valign="top">Did you live through this meal?  :)  I like the colors and sharpness.  And now I''m hungry.</td>', 'Did you live through this meal?  :)  I like the colors and sharpness.  And now I''m hungry.', '2003-06-02 11:41:28.000000', NULL, 1),
(312679, 23320, 7707, '<td valign="top">great shot.</td>', 'great shot.', '2003-06-02 11:41:42.000000', NULL, 1),
(312684, 23002, 7707, '<td valign="top">Great idea and shot, no pun intended.  It portrays motion better than sound, but still a great shot!</td>', 'Great idea and shot, no pun intended.  It portrays motion better than sound, but still a great shot!', '2003-06-02 11:44:52.000000', NULL, 1),
(312703, 23234, 5982, '<td valign="top">photo is nice but the fact we can''t see the eyes of the man is disturbing, IMHO.  The rest of the shot is superb.</td>', 'photo is nice but the fact we can''t see the eyes of the man is disturbing, IMHO.  The rest of the shot is superb.', '2003-06-02 12:59:07.000000', NULL, 1),
(312705, 23156, 5391, '<td valign="top">Awesome.  The captured vibration of the string really is in the essence of the challenge.  Great contrast in the colors and great composition!  10</td>', 'Awesome.  The captured vibration of the string really is in the essence of the challenge.  Great contrast in the colors and great composition!  10', '2003-06-02 13:05:17.000000', NULL, 1),
(312727, 23337, 7707, '<td valign="top">Good subject - photo quality just a bit dark and keys that aren''t being played are blury.</td>', 'Good subject - photo quality just a bit dark and keys that aren''t being played are blury.', '2003-06-02 13:25:45.000000', NULL, 1),
(312728, 22876, 6678, '<td valign="top">Superb - there really isn''t anything more to say. 10.</td>', 'Superb - there really isn''t anything more to say. 10.', '2003-06-02 13:25:52.000000', NULL, 1),
(312731, 23538, 6678, '<td valign="top">Nice Vette :o) Clever idea.</td>', 'Nice Vette :o) Clever idea.', '2003-06-02 13:27:38.000000', NULL, 1),
(312732, 22840, 6678, '<td valign="top">Clever title...</td>', 'Clever title...', '2003-06-02 13:28:12.000000', NULL, 1),
(312733, 23131, 6678, '<td valign="top">Ho, ho, ho</td>', 'Ho, ho, ho', '2003-06-02 13:28:28.000000', NULL, 1),
