(313115, 23502, 7350, '<td valign="top">Some washed out spots, but good texture overall.</td>', 'Some washed out spots, but good texture overall.', '2003-06-02 18:04:33.000000', NULL, 1),
(313117, 23165, 8530, '<td valign="top">Another shot where I had to focus quite closely to figure out what it was -- a violin or similar stringed instrument, si? Because of that, I''m not fond of the image and it didn''t strongly evoke ''sound'' for me, although it is on topic.</td>', 'Another shot where I had to focus quite closely to figure out what it was -- a violin or similar stringed instrument, si? Because of that, I''m not fond of the image and it didn''t strongly evoke ''sound'' for me, although it is on topic.', '2003-06-02 18:05:46.000000', NULL, 1),
