INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(319113, 23517, 5792, '<td valign="top">Black background is perfect for this image. The blue color makes this image special.</td>', 'Black background is perfect for this image. The blue color makes this image special.', '2003-06-08 21:41:29.000000', NULL, 1),
(319114, 22876, 5792, '<td valign="top">Great concept, well executed. One of the best for this challenge.</td>', 'Great concept, well executed. One of the best for this challenge.', '2003-06-08 21:42:23.000000', NULL, 1),
(319117, 23308, 554, '<td valign="top">perfect exposure were it not for that one errant string.....Nice photo..10</td>', 'perfect exposure were it not for that one errant string.....Nice photo..10', '2003-06-08 21:42:31.000000', NULL, 1),
(319119, 23386, 5792, '<td valign="top">Well composed and good technical quality. The blue lighting helps make this an excellant image.</td>', 'Well composed and good technical quality. The blue lighting helps make this an excellant image.', '2003-06-08 21:43:32.000000', NULL, 1),
(319120, 23529, 5792, '<td valign="top">Great angle and well composed. You captured the concept of sound very well in the face of your subject.</td>', 'Great angle and well composed. You captured the concept of sound very well in the face of your subject.', '2003-06-08 21:44:37.000000', NULL, 1),
(319124, 23357, 554, '<td valign="top">This is one of my favorites, in fact it is this weeks wallpaper....10</td>', 'This is one of my favorites, in fact it is this weeks wallpaper....10', '2003-06-08 21:45:37.000000', NULL, 1),
(319125, 23551, 5792, '<td valign="top">Very well concieved image. Super concept having sheet music below water with "sound" waves captured in the image. One of the best for this challenge.</td>', 'Very well concieved image. Super concept having sheet music below water with "sound" waves captured in the image. One of the best for this challenge.', '2003-06-08 21:47:42.000000', NULL, 1),
(319127, 23511, 5792, '<td valign="top">Good quality image. Unique.</td>', 'Good quality image. Unique.', '2003-06-08 21:48:19.000000', NULL, 1),
(319128, 23370, 5792, '<td valign="top">The human subject following ROT is really nice. Tecnical high quality image.</td>', 'The human subject following ROT is really nice. Tecnical high quality image.', '2003-06-08 21:49:51.000000', NULL, 1),
(319129, 23549, 5792, '<td valign="top">Good capture of something very difficult to capture.</td>', 'Good capture of something very difficult to capture.', '2003-06-08 21:50:31.000000', NULL, 1),
(319132, 23335, 5792, '<td valign="top">High quality image. Great capture.</td>', 'High quality image. Great capture.', '2003-06-08 21:51:33.000000', NULL, 1),
(319133, 23002, 5792, '<td valign="top">I can hear the classic sound of the cue ball hitting the racked balls. Very well done.</td>', 'I can hear the classic sound of the cue ball hitting the racked balls. Very well done.', '2003-06-08 21:52:47.000000', NULL, 1),
(319136, 22947, 5792, '<td valign="top">Excellant quality, focus and composition.</td>', 'Excellant quality, focus and composition.', '2003-06-08 21:53:33.000000', NULL, 1),
(319137, 23324, 5792, '<td valign="top">Really like the DOF, color and focus of this image.</td>', 'Really like the DOF, color and focus of this image.', '2003-06-08 21:54:13.000000', NULL, 1),
(319156, 23131, 7628, '<td valign="top">Great idea!  A sound we all hear every day.   I like the composition, but wish things were in sharper focus, and would like to see what ot looks like in b&amp;w.</td>', 'Great idea!  A sound we all hear every day.   I like the composition, but wish things were in sharper focus, and would like to see what ot looks like in b&w.', '2003-06-08 22:34:46.000000', NULL, 1),
(319161, 23551, 7628, '<td valign="top">Very nice idea!  You captured the vibrations very nicely.  Having the sheet music in the background completes the composition well.  I might have cropped in the sides. 8</td>', 'Very nice idea!  You captured the vibrations very nicely.  Having the sheet music in the background completes the composition well.  I might have cropped in the sides. 8', '2003-06-08 22:44:29.000000', NULL, 1),
(319165, 23527, 7628, '<td valign="top">B&amp;W is a good choice - the carpet and the skirt look like they;d be too busy in color.  I''d like to see the dancer on a darker floor too.  Still I like the focus on the feet from behind - really brings it down to the bells, and having the dancer up on toes gives sense of the motion which makes the bells ring.</td>', 'B&W is a good choice - the carpet and the skirt look like they;d be too busy in color.  I''d like to see the dancer on a darker floor too.  Still I like the focus on the feet from behind - really brings it down to the bells, and having the dancer up on toes gives sense of the motion which makes the bells ring.', '2003-06-08 22:50:32.000000', NULL, 1),
(319167, 23530, 7628, '<td valign="top">Nice composition and color choice.  Gives a very sea lion feel.  You can almost hear that loud bark filling the space around the head.</td>', 'Nice composition and color choice.  Gives a very sea lion feel.  You can almost hear that loud bark filling the space around the head.', '2003-06-08 22:52:58.000000', NULL, 1),
(319169, 23357, 7628, '<td valign="top">Very relaxing.  The composition is excellent - the reflections in the water, the person sitting in the space between the mountain peaks, the reflection of the blue sky in the still water - very peacful and quiet.  A sound we could all use more of! 9</td>', 'Very relaxing.  The composition is excellent - the reflections in the water, the person sitting in the space between the mountain peaks, the reflection of the blue sky in the still water - very peacful and quiet.  A sound we could all use more of! 9', '2003-06-08 22:56:47.000000', NULL, 1),
(319170, 23523, 7711, '<td valign="top">I like your use of shadow,  it brings attention to the now popped balloon. :) Good feeling of sound and motion here too. well done.</td>', 'I like your use of shadow,  it brings attention to the now popped balloon. :) Good feeling of sound and motion here too. well done.', '2003-06-08 23:01:08.000000', NULL, 1),
(319171, 23543, 7711, '<td valign="top">very neat composition idea, this totally fits the challenge, and I like the dark background..the lack of too many contrasting colours keeps attention on the motion of the water. :)</td>', 'very neat composition idea, this totally fits the challenge, and I like the dark background..the lack of too many contrasting colours keeps attention on the motion of the water. :)', '2003-06-08 23:02:17.000000', NULL, 1),
(319172, 23425, 7628, '<td valign="top">Beautiful as usual!  The moist eyes, the way the light moulds the facial features, soft fringes of hair, curving figers on the head phones, head tilting, listenning.  The "sound" is subtle - doesn''t hit you over the head - I like that. 10</td>', 'Beautiful as usual!  The moist eyes, the way the light moulds the facial features, soft fringes of hair, curving figers on the head phones, head tilting, listenning.  The "sound" is subtle - doesn''t hit you over the head - I like that. 10', '2003-06-08 23:02:50.000000', NULL, 1),
(319173, 23320, 7711, '<td valign="top">nice. :) Reminds me of the old player piano rolls. I haven''t seen a music box like this since I was a kid.</td>', 'nice. :) Reminds me of the old player piano rolls. I haven''t seen a music box like this since I was a kid.', '2003-06-08 23:03:51.000000', NULL, 1),
(319174, 23407, 7711, '<td valign="top">I like the milk pouring action. :) Maybe some strawberries in the bowl would have jazzed up the composition. :)</td>', 'I like the milk pouring action. :) Maybe some strawberries in the bowl would have jazzed up the composition. :)', '2003-06-08 23:04:27.000000', NULL, 1),
(319175, 23370, 7711, '<td valign="top">great use of silhouette and backlighting. :) I like the shape of the person in behind.</td>', 'great use of silhouette and backlighting. :) I like the shape of the person in behind.', '2003-06-08 23:05:28.000000', NULL, 1),
(319176, 23509, 7711, '<td valign="top">meets the challenge, but I can''t say I find this compositionally very exciting.</td>', 'meets the challenge, but I can''t say I find this compositionally very exciting.', '2003-06-08 23:05:59.000000', NULL, 1),
(319177, 23544, 7711, '<td valign="top">i would have liked the focus/attention to have been more on the bell portion, its hard to see the motion blur at first with this composition.</td>', 'i would have liked the focus/attention to have been more on the bell portion, its hard to see the motion blur at first with this composition.', '2003-06-08 23:06:54.000000', NULL, 1),
(319181, 23360, 7711, '<td valign="top">a diffuser on your light would have helped with that distracting shadow. Also find the crop to be a bit tight. She looks like she''s been jammed into a closet to play!</td>', 'a diffuser on your light would have helped with that distracting shadow. Also find the crop to be a bit tight. She looks like she''s been jammed into a closet to play!', '2003-06-08 23:07:43.000000', NULL, 1),
(319186, 23165, 7711, '<td valign="top">love your choice of duotones, and the abstract angle. The reflection of the bridge is very effective. Very well done.</td>', 'love your choice of duotones, and the abstract angle. The reflection of the bridge is very effective. Very well done.', '2003-06-08 23:13:26.000000', NULL, 1),
(319189, 23384, 7711, '<td valign="top">one of the nicest of piano/hand shots. Lighting is not too harsh, and I get a sense of music without odd finger motion blurs.</td>', 'one of the nicest of piano/hand shots. Lighting is not too harsh, and I get a sense of music without odd finger motion blurs.', '2003-06-08 23:16:31.000000', NULL, 1),
(319192, 23448, 7711, '<td valign="top">I haven''t a clue what this is. I''m going to imagine its ice and an ice pick. I hope you can relieve me of my ignorance on this soon!</td>', 'I haven''t a clue what this is. I''m going to imagine its ice and an ice pick. I hope you can relieve me of my ignorance on this soon!', '2003-06-08 23:17:54.000000', NULL, 1),
(319196, 23518, 7711, '<td valign="top">what a great composition. I don\''t care for the border, I think its a bit heavy for the gentleness and motion of the shot, but its ok. Love this.</td>', 'what a great composition. I don\''t care for the border, I think its a bit heavy for the gentleness and motion of the shot, but its ok. Love this.', '2003-06-08 23:19:56.000000', NULL, 1),
(319198, 23503, 1847, '<td valign="top">This one mighta been better had you cropped a little wider, to get some of the non-moving part of the speaker in there to give a context for the cone.  As it is, it just looks out of focus, even though I know it''s not.</td>', 'This one mighta been better had you cropped a little wider, to get some of the non-moving part of the speaker in there to give a context for the cone.  As it is, it just looks out of focus, even though I know it''s not.', '2003-06-08 23:21:06.000000', NULL, 1),
(319199, 23379, 6870, '<td valign="top">I can''t imagine a more perfect candid shot. This is lovely. Cropping and composition are wonderful. Real joy to be found here! 10</td>', 'I can''t imagine a more perfect candid shot. This is lovely. Cropping and composition are wonderful. Real joy to be found here! 10', '2003-06-08 23:21:06.000000', NULL, 1),
(319200, 23516, 6900, '<td valign="top">Holy cow, I smell the pounds!  Nice sound.</td>', 'Holy cow, I smell the pounds!  Nice sound.', '2003-06-08 23:21:36.000000', NULL, 1),
(319201, 23401, 6870, '<td valign="top">You found the perfect way to show air going through this instrument. Add a touch of drama with composition and lighting and viola! You''ve got a great picture! 10</td>', 'You found the perfect way to show air going through this instrument. Add a touch of drama with composition and lighting and viola! You''ve got a great picture! 10', '2003-06-08 23:22:08.000000', NULL, 1),
(319202, 23394, 6870, '<td valign="top">The lighting and tones here are so warm and intimate, this is just wonderful 10</td>', 'The lighting and tones here are so warm and intimate, this is just wonderful 10', '2003-06-08 23:22:43.000000', NULL, 1),
(319203, 23526, 6870, '<td valign="top">The motion blur and somewhat harsh lighting really work well together here. Good choices!</td>', 'The motion blur and somewhat harsh lighting really work well together here. Good choices!', '2003-06-08 23:23:25.000000', NULL, 1),
(319206, 23533, 6870, '<td valign="top">I love the motion blurhere. Your cropping is perfect, too.I like the darker tones. I really can "hear'' the sound here!</td>', 'I love the motion blurhere. Your cropping is perfect, too.I like the darker tones. I really can "hear'' the sound here!', '2003-06-08 23:24:22.000000', NULL, 1),
(319208, 23527, 6870, '<td valign="top">Wonderful! One of my favorites for this challenge. Perfect composition/cropping.</td>', 'Wonderful! One of my favorites for this challenge. Perfect composition/cropping.', '2003-06-08 23:25:25.000000', NULL, 1),
(319209, 23530, 6870, '<td valign="top">I''m not sure why you chose this color, but I love the composition and cropping. Great timing,too. Super photo!</td>', 'I''m not sure why you chose this color, but I love the composition and cropping. Great timing,too. Super photo!', '2003-06-08 23:26:11.000000', NULL, 1),
(319210, 23529, 6870, '<td valign="top">Composition and point of view here suggest that her whole body is screaming. It really works!</td>', 'Composition and point of view here suggest that her whole body is screaming. It really works!', '2003-06-08 23:26:52.000000', NULL, 1),
(319211, 22876, 6870, '<td valign="top">Classic way to show sound! Nice stop motion!</td>', 'Classic way to show sound! Nice stop motion!', '2003-06-08 23:27:39.000000', NULL, 1),
(319212, 23314, 6870, '<td valign="top">Motion blur is fabulous. I really get a sense of sound here.</td>', 'Motion blur is fabulous. I really get a sense of sound here.', '2003-06-08 23:28:15.000000', NULL, 1),
(319213, 23524, 6870, '<td valign="top">Lighting really adds drama here. This looks like my wife''s. It may even be the same unit. Nice work!</td>', 'Lighting really adds drama here. This looks like my wife''s. It may even be the same unit. Nice work!', '2003-06-08 23:29:06.000000', NULL, 1),
(319214, 23546, 6870, '<td valign="top">I love the point of view, and the motion blur works very well here!</td>', 'I love the point of view, and the motion blur works very well here!', '2003-06-08 23:29:40.000000', NULL, 1),
(319215, 22947, 6870, '<td valign="top">I suppose you mean "in a PREVIOUS existence?" No matter. I love the point of view here,and your lighting could not be better. Super work!</td>', 'I suppose you mean "in a PREVIOUS existence?" No matter. I love the point of view here,and your lighting could not be better. Super work!', '2003-06-08 23:30:41.000000', NULL, 1),
(319216, 22855, 6870, '<td valign="top">The high key lighting here almost suggests a high key noise! At least to me... Wonderful emotion and work!</td>', 'The high key lighting here almost suggests a high key noise! At least to me... Wonderful emotion and work!', '2003-06-08 23:31:29.000000', NULL, 1),
(319218, 23551, 6870, '<td valign="top">I tried doing this for an hour before giving up! Yours is much better. Wonderful idea! Your lighting and composition are wonderful!</td>', 'I tried doing this for an hour before giving up! Yours is much better. Wonderful idea! Your lighting and composition are wonderful!', '2003-06-08 23:33:40.000000', NULL, 1),
(319219, 23002, 6870, '<td valign="top">Super stop motion photo. Unique idea for sound, too. I like it lots!</td>', 'Super stop motion photo. Unique idea for sound, too. I like it lots!', '2003-06-08 23:34:24.000000', NULL, 1),
(319220, 23513, 6870, '<td valign="top">Wonderful idea and execution. point of view is perfect for implying sound.</td>', 'Wonderful idea and execution. point of view is perfect for implying sound.', '2003-06-08 23:34:57.000000', NULL, 1),
(319221, 23234, 6870, '<td valign="top">Lovely shot. Composition is wonderful. The choice of blocking his face is probably appropriate, but I''d sure like to see it!</td>', 'Lovely shot. Composition is wonderful. The choice of blocking his face is probably appropriate, but I''d sure like to see it!', '2003-06-08 23:35:52.000000', NULL, 1),
(319222, 23425, 6870, '<td valign="top">He''s still a good looking boy. Must take after his dad! I like the close in crop of the face here, and I''m glad you included the headphones. As always, wonderful lighting and tones.</td>', 'He''s still a good looking boy. Must take after his dad! I like the close in crop of the face here, and I''m glad you included the headphones. As always, wonderful lighting and tones.', '2003-06-08 23:37:27.000000', NULL, 1),
(319223, 23308, 6870, '<td valign="top">Groovy idea! The many different lines lead my eye around the photo very effectively, but I always end up looking, appropriately, at the vibrating string. Nice work!</td>', 'Groovy idea! The many different lines lead my eye around the photo very effectively, but I always end up looking, appropriately, at the vibrating string. Nice work!', '2003-06-08 23:38:31.000000', NULL, 1),
(319224, 23197, 6870, '<td valign="top">Super journalistic shot here. The motion blur  implies sound, too. Very nice!</td>', 'Super journalistic shot here. The motion blur  implies sound, too. Very nice!', '2003-06-08 23:39:05.000000', NULL, 1),
(319225, 23464, 6870, '<td valign="top">Cool lighting. Great composition. Good picture.</td>', 'Cool lighting. Great composition. Good picture.', '2003-06-08 23:39:50.000000', NULL, 1),
(319226, 23494, 6870, '<td valign="top">Motion blur is great, but the photo would improve greatly if it were contrasted with very focused, clear keys. Still,  nice work.</td>', 'Motion blur is great, but the photo would improve greatly if it were contrasted with very focused, clear keys. Still,  nice work.', '2003-06-08 23:41:22.000000', NULL, 1),
(319229, 23537, 6870, '<td valign="top">Sure looks fun,and the splash does imply sound here.</td>', 'Sure looks fun,and the splash does imply sound here.', '2003-06-08 23:43:08.000000', NULL, 1),
(319231, 23320, 6870, '<td valign="top">It''s kind of subtle, but I can see a few of those prongs in movement. Perhaps a perspective closer to the prongs and lower would help us see their movement even more.</td>', 'It''s kind of subtle, but I can see a few of those prongs in movement. Perhaps a perspective closer to the prongs and lower would help us see their movement even more.', '2003-06-08 23:45:44.000000', NULL, 1),
(319232, 23407, 6870, '<td valign="top">Fun idea! Adding the milk is a nice touch, as that''s what makes the cereal make the noise. Very nice.</td>', 'Fun idea! Adding the milk is a nice touch, as that''s what makes the cereal make the noise. Very nice.', '2003-06-08 23:46:46.000000', NULL, 1),
(319235, 23370, 6870, '<td valign="top">Fun contrast! I''d like some hint that the trumpet is actually making noise, though. Wonderful composition and lighting.</td>', 'Fun contrast! I''d like some hint that the trumpet is actually making noise, though. Wonderful composition and lighting.', '2003-06-08 23:48:04.000000', NULL, 1),
(319238, 23466, 6870, '<td valign="top">Great idea! You can really "see" sound with the water acting proxy for air. I''d like to see it turned 90 degrees CCW and see it horizontal.</td>', 'Great idea! You can really "see" sound with the water acting proxy for air. I''d like to see it turned 90 degrees CCW and see it horizontal.', '2003-06-08 23:50:56.000000', NULL, 1),
(319241, 23502, 6870, '<td valign="top">Nice shot. Whites are a bit blown out in the lower left corner, but this doesn''t bother me much. Good shot.</td>', 'Nice shot. Whites are a bit blown out in the lower left corner, but this doesn''t bother me much. Good shot.', '2003-06-08 23:52:10.000000', NULL, 1),
(319245, 23496, 6325, '<td valign="top">Nice tones in the image. Well composed. Soothing yet powerful. A full orchestra.</td>', 'Nice tones in the image. Well composed. Soothing yet powerful. A full orchestra.', '2003-06-08 23:54:41.000000', NULL, 1),
(319246, 23549, 6870, '<td valign="top">How many light bulbs did you break to get this one! Nice work!</td>', 'How many light bulbs did you break to get this one! Nice work!', '2003-06-08 23:54:47.000000', NULL, 1),
(319247, 23427, 6870, '<td valign="top">Very nice still life. I kind of wish they weren''t so still, though, to suggest sound more. Nice lighting and composition!</td>', 'Very nice still life. I kind of wish they weren''t so still, though, to suggest sound more. Nice lighting and composition!', '2003-06-08 23:55:40.000000', NULL, 1),
(319248, 23544, 6870, '<td valign="top">Nice shot! The ring is fairly apparent, but perhaps a bit closer to the bells would help us see this motion blur better.</td>', 'Nice shot! The ring is fairly apparent, but perhaps a bit closer to the bells would help us see this motion blur better.', '2003-06-08 23:56:34.000000', NULL, 1),
(319249, 23345, 6870, '<td valign="top">The action of this shot does imply sound quite nicely. Nice  composition and sense of motion.</td>', 'The action of this shot does imply sound quite nicely. Nice  composition and sense of motion.', '2003-06-08 23:57:29.000000', NULL, 1),
